#include <bits/stdc++.h>
using namespace std;

int main() {
// your code goes here
 ios::sync_with_stdio(false);
 cin.tie(nullptr);
 int t;
 cin>>t;
 while(t--){
     int n;
     cin>>n;
     int m=3*n;
     vector<long long>a(m),p(m+1);
     for(auto &x:a) cin>>x;
     sort(a.begin(),a.end());
     for(int i=0;i<m;i++)
     p[i+1]=p[i]+a[i];
     long long ans=0;
     for(int A=0;A<=n;A++){
         int lo=0,hi=n-A;
         auto delta=[&](int B){
        int i=2*A+B;
        int j=m-A-2*B-2;
        return a[j]+a[j+1]-3*a[i];
         };
         int B=0;
         if (delta(0)>=0){
             while(lo<hi){
                 int mid=(lo+hi+1)/2;
                 if(delta(mid)>=0)
                 lo= mid;
                 else
                 hi=mid-1;
                 
             }
            B=lo; 
         }
         for(int x=B;x<=min(B+1,n-A);x++){
             int C =n-A-x;
             int z=2*A+x;
             long long cur=
             3*(p[z+3*C]-p[z])+4*(p[z+3*C+2*x]-p[z+3*C])+6*(p[m]-p[z+3*C+2*x]);
            ans=max(ans,cur);
             
         }
         }
         cout<<ans<<'\n';
         
 }
 return 0;
}
